// spec: specs/data-requests-reauth.md (1.2) · кейс DR-02 · запасной путь (MCP playwright-test отключён)
// seed: tests/seed.parent-b.spec.ts
// /settings → «מחיקת כל נתוני המשפחה» → «שליחת הבקשה» → окно → «ביטול». Необратимый запрос НЕ отправляется.
import { test, expect } from '@playwright/test';
import { PARENT_B, T, blockDataRequestWrites, cancelReauth, expectReauthDialog, sendButton, visibleText } from './data-requests.helpers';

test.use({ storageState: PARENT_B, viewport: { width: 1280, height: 800 } });

test.describe('Запросы данных — «אימות זהות» перед удалением', () => {
  test('Удаление всей семьи из /settings: окно «אימות זהות», без POST; «ביטול» @desktop @prod-safe #c3aa39', async ({ page }) => {
    const writes = await blockDataRequestWrites(page);
    await page.goto('/settings');
    await visibleText(page, T.settingsFamilyLink).click();

    // Форма открыта сразу с действием «למחוק את כל נתוני המשפחה» (скрин c3aa39-T2-settings-family)
    await expect(page).toHaveURL(/\/privacy\/data-request/);
    await expect(page.getByText(T.deleteFamilyHint).filter({ visible: true }).first()).toBeVisible();

    await sendButton(page).click();
    await expectReauthDialog(page);
    expect(writes, `до пароля не было записи запроса: ${JSON.stringify(writes)}`).toEqual([]);

    await cancelReauth(page);
    await expect(page.getByText(T.deleteFamilyHint).filter({ visible: true }).first()).toBeVisible();
    await expect(sendButton(page)).toBeVisible();
    expect(writes, 'после «ביטול» запрос не создан').toEqual([]);
  });
});
